import '../models/question.dart';

class PharmacologyQuestions {
  static final List<Question> questions = [
    Question(id: 'phar_001', category: 'pharmacology', subcategory: 'analgesics', type: 'test', difficulty: 'easy', questionText: 'Ağrı kesici ve ateş düşürücü olarak en yaygın kullanılan ilaç hangisidir?', options: ['Amoksisilin', 'Parasetamol', 'Omeprazol', 'Metformin'], correctAnswer: 'Parasetamol', explanation: 'Parasetamol (Asetaminofen) en yaygın analjezik ve antipiretiktir. Antiinflamatuar etkisi zayıftır. Karaciğer toksisitesi riski vardır.'),
    Question(id: 'phar_002', category: 'pharmacology', subcategory: 'analgesics', type: 'test', difficulty: 'medium', questionText: 'NSAİD ilaçların etki mekanizması nedir?', options: ['Opioid reseptör aktivasyonu', 'COX enzim inhibisyonu', 'GABA reseptör aktivasyonu', 'Serotonin geri alım inhibisyonu'], correctAnswer: 'COX enzim inhibisyonu', explanation: 'NSAİD\'ler (Aspirin, İbuprofen, Naproksen) COX (siklooksijenaz) enzimini inhibe ederek prostaglandin sentezini azaltır. Anti-inflamatuar, analjezik ve antipiretik etki gösterir.'),
    Question(id: 'phar_003', category: 'pharmacology', subcategory: 'analgesics', type: 'test', difficulty: 'medium', questionText: 'Aspirin\'in kan sulandırıcı etkisi hangi mekanizmayla olur?', options: ['Vitamin K antagonizması', 'Tromboksan A2 inhibisyonu', 'Fibrinojen inhibisyonu', 'Antitrombin III aktivasyonu'], correctAnswer: 'Tromboksan A2 inhibisyonu', explanation: 'Aspirin, trombositlerde COX-1 enzimini geri dönüşümsüz inhibe ederek Tromboksan A2 yapımını engeller. Bu trombosit agregasyonunu azaltır.'),
    Question(id: 'phar_004', category: 'pharmacology', subcategory: 'antibiotics', type: 'test', difficulty: 'easy', questionText: 'Penisilin hangi tür mikroorganizmalara karşı etkilidir?', options: ['Virüsler', 'Bakteriler', 'Mantarlar', 'Parazitler'], correctAnswer: 'Bakteriler', explanation: 'Penisilin bir antibiyotiktir ve bakterilere karşı etkilidir. Bakteri hücre duvarı sentezini inhibe eder.'),
    Question(id: 'phar_005', category: 'pharmacology', subcategory: 'antibiotics', type: 'test', difficulty: 'medium', questionText: 'Beta-laktam antibiyotiklerin etki mekanizması nedir?', options: ['Protein sentezi inhibisyonu', 'Hücre duvarı sentezi inhibisyonu', 'DNA sentezi inhibisyonu', 'Folat sentezi inhibisyonu'], correctAnswer: 'Hücre duvarı sentezi inhibisyonu', explanation: 'Beta-laktamlar (penisilinler, sefalosporinler, karbapenemler) bakteri hücre duvarındaki peptidoglikan sentezini inhibe eder.'),
    Question(id: 'phar_006', category: 'pharmacology', subcategory: 'antibiotics', type: 'test', difficulty: 'hard', questionText: 'Vankomisin hangi tür bakterilere karşı kullanılır?', options: ['Gram negatif', 'Gram pozitif (özellikle MRSA)', 'Anaeroblar', 'Mikobakteriler'], correctAnswer: 'Gram pozitif (özellikle MRSA)', explanation: 'Vankomisin, gram pozitif bakterilere karşı etkili glikopeptid antibiyotiktir. MRSA enfeksiyonlarında son çare olarak kullanılır.'),
    Question(id: 'phar_007', category: 'pharmacology', subcategory: 'antibiotics', type: 'test', difficulty: 'medium', questionText: 'Makrolid grubu antibiyotiklere örnek hangisidir?', options: ['Amoksisilin', 'Azitromisin', 'Siprofloksasin', 'Gentamisin'], correctAnswer: 'Azitromisin', explanation: 'Makrolidler (Eritromisin, Azitromisin, Klaritromisin) bakteri ribozomunda 50S alt ünitesine bağlanarak protein sentezini inhibe eder.'),

    // FARMAKOKİNETİK
    Question(id: 'phar_008', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Farmakokinetik ne inceler?', options: ['İlacın vücuda etkisini', 'Vücudun ilaca ne yaptığını', 'İlaç etkileşimlerini', 'İlaç yan etkilerini'], correctAnswer: 'Vücudun ilaca ne yaptığını', explanation: 'Farmakokinetik, vücudun ilaca ne yaptığını inceler: ADME (Absorpsiyon, Distribüsyon, Metabolizma, Eliminasyon).'),
    Question(id: 'phar_009', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Farmakodinami ne inceler?', options: ['İlacın emilimini', 'İlacın vücuttaki dağılımını', 'İlacın vücuda etkisini', 'İlacın atılımını'], correctAnswer: 'İlacın vücuda etkisini', explanation: 'Farmakodinami, ilacın vücuda ne yaptığını inceler: reseptör etkileşimleri, etki mekanizması, doz-yanıt ilişkisi.'),
    Question(id: 'phar_010', category: 'pharmacology', subcategory: 'general', type: 'open', difficulty: 'hard', questionText: 'İlacın yarı ömrü (t1/2) ne demektir?', correctAnswer: 'İlacın plazma konsantrasyonunun yarıya düşme süresi', explanation: 'Yarı ömür, ilacın plazma konsantrasyonunun %50 azalması için geçen süredir. Doz aralığının belirlenmesinde önemlidir.'),
    Question(id: 'phar_011', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'İlaçların büyük çoğunluğu hangi organda metabolize edilir?', options: ['Böbrek', 'Karaciğer', 'Bağırsak', 'Akciğer'], correctAnswer: 'Karaciğer', explanation: 'Karaciğer, ilaç metabolizmasının ana organıdır. Sitokrom P450 enzim sistemi birçok ilacın metabolizmasından sorumludur.'),
    Question(id: 'phar_012', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Birinci geçiş etkisi (first-pass effect) nedir?', options: ['İlacın böbrekten ilk atılımı', 'İlacın oral alım sonrası karaciğerde metabolize edilmesi', 'İlacın beyine ilk ulaşması', 'İlacın plasentadan geçmesi'], correctAnswer: 'İlacın oral alım sonrası karaciğerde metabolize edilmesi', explanation: 'Birinci geçiş etkisi, oral alınan ilacın emilip portal ven yoluyla karaciğere ulaştığında, sistemik dolaşıma girmeden önce metabolize edilmesidir.'),

    // KARDİYOVASKÜLER İLAÇLAR
    Question(id: 'phar_013', category: 'pharmacology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'ACE inhibitörleri (enalapril, ramipril) ne için kullanılır?', options: ['Diyabet tedavisi', 'Hipertansiyon ve kalp yetmezliği', 'Enfeksiyon tedavisi', 'Epilepsi tedavisi'], correctAnswer: 'Hipertansiyon ve kalp yetmezliği', explanation: 'ACE inhibitörleri, anjiyotensin dönüştürücü enzimi inhibe ederek kan basıncını düşürür. Kalp yetmezliğinde prognoz iyileştirir.'),
    Question(id: 'phar_014', category: 'pharmacology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Beta-bloker ilaçların kalp üzerindeki etkisi nedir?', options: ['Kalp hızını artırır', 'Kalp hızını ve kasılma gücünü azaltır', 'Kan basıncını artırır', 'Kalp debisini artırır'], correctAnswer: 'Kalp hızını ve kasılma gücünü azaltır', explanation: 'Beta-blokerler (metoprolol, atenolol) kalpteki beta-1 reseptörlerini bloke ederek kalp hızını ve kasılma gücünü azaltır. Hipertansiyon, angina ve aritmi tedavisinde kullanılır.'),
    Question(id: 'phar_015', category: 'pharmacology', subcategory: 'cardiovascular', type: 'test', difficulty: 'hard', questionText: 'Warfarin\'in antidotu nedir?', options: ['Protamin sülfat', 'K vitamini', 'N-asetilsistein', 'Flumazenil'], correctAnswer: 'K vitamini', explanation: 'Warfarin K vitamini antagonistidir. Antidotu K vitaminidir. Acil durumlarda taze donmuş plazma (TDP) da verilebilir.'),

    // DİĞER İLAÇLAR
    Question(id: 'phar_016', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'easy', questionText: 'Omeprazol ne için kullanılır?', options: ['Ağrı kesici', 'Mide asidi baskılayıcı', 'Antibiyotik', 'Tansiyon düşürücü'], correctAnswer: 'Mide asidi baskılayıcı', explanation: 'Omeprazol bir proton pompası inhibitörüdür (PPİ). Mide parietal hücrelerinde H+/K+ ATPaz pompasını inhibe ederek asit salgısını azaltır.'),
    Question(id: 'phar_017', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Metformin hangi hastalıkta kullanılır?', options: ['Hipertansiyon', 'Tip 2 Diyabet', 'Astım', 'Epilepsi'], correctAnswer: 'Tip 2 Diyabet', explanation: 'Metformin, Tip 2 diyabetin birinci basamak tedavisidir. Karaciğerde glukoz üretimini azaltır ve insülin duyarlılığını artırır.'),
    Question(id: 'phar_018', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Adrenalin (epinefrin) hangi acil durumda ilk tercih edilen ilaçtır?', options: ['Kalp krizi', 'Anafilaksi', 'İnme', 'Pnömotoraks'], correctAnswer: 'Anafilaksi', explanation: 'Adrenalin, anafilaksinin (şiddetli alerjik reaksiyon) tedavisinde ilk seçenek ilaçtır. Bronkodilatasyon sağlar, vazokonstriksiyon yapar ve kalp debisini artırır.'),
    Question(id: 'phar_019', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Parasetamol zehirlenmesinde kullanılan antidot nedir?', options: ['K vitamini', 'Nalokson', 'N-asetilsistein (NAC)', 'Atropin'], correctAnswer: 'N-asetilsistein (NAC)', explanation: 'N-asetilsistein (NAC), parasetamol zehirlenmesinin spesifik antidotudur. Karaciğerde glutatyon depolarını yenileyerek toksik metabolitin nötralizasyonunu sağlar.'),
    Question(id: 'phar_020', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Opioid zehirlenmesinde kullanılan antidot nedir?', options: ['Flumazenil', 'Nalokson', 'Atropin', 'Pralidoksim'], correctAnswer: 'Nalokson', explanation: 'Nalokson, opioid reseptör antagonistidir ve opioid zehirlenmesinin (solunum depresyonu, koma) spesifik antidotudur.'),
  ];
}

class PathologyQuestions {
  static final List<Question> questions = [
    // GENEL PATOLOJİ
    Question(id: 'path_001', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'easy', questionText: 'İltihap (enflamasyon) belirtileri hangileridir?', options: ['Kızarıklık, şişlik, ağrı, ısı artışı, fonksiyon kaybı', 'Sadece ateş ve halsizlik', 'Sadece kızarıklık ve kaşıntı', 'Sadece ağrı ve şişlik'], correctAnswer: 'Kızarıklık, şişlik, ağrı, ısı artışı, fonksiyon kaybı', explanation: 'İltihabın 5 kardinal belirtisi: Rubor (kızarıklık), Tumor (şişlik), Dolor (ağrı), Calor (ısı artışı), Functio laesa (fonksiyon kaybı).'),
    Question(id: 'path_002', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Hücrelerin kontrolsüz çoğalmasına ne denir?', options: ['Hipertrofi', 'Hiperplazi', 'Neoplazi', 'Metaplazi'], correctAnswer: 'Neoplazi', explanation: 'Neoplazi, hücrelerin kontrolsüz ve anormal çoğalmasıdır. Benign veya malign olabilir.'),
    Question(id: 'path_003', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Hücre büyüklüğünün artmasına ne denir?', options: ['Hiperplazi', 'Hipertrofi', 'Metaplazi', 'Displazi'], correctAnswer: 'Hipertrofi', explanation: 'Hipertrofi, hücre sayısı değişmeden hücre büyüklüğünün artmasıdır. Örnek: Kalp kası hipertrofisi, iskelet kası hipertrofisi.'),
    Question(id: 'path_004', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Hücre sayısının artmasına ne denir?', options: ['Hipertrofi', 'Hiperplazi', 'Atrofi', 'Neoplazi'], correctAnswer: 'Hiperplazi', explanation: 'Hiperplazi, hücre sayısının artmasıdır. Fizyolojik (gebelikte meme büyümesi) veya patolojik (endometrial hiperplazi) olabilir.'),
    Question(id: 'path_005', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Bir hücre tipinin başka bir hücre tipine dönüşmesine ne denir?', options: ['Displazi', 'Metaplazi', 'Neoplazi', 'Anaplazi'], correctAnswer: 'Metaplazi', explanation: 'Metaplazi, olgun bir hücre tipinin başka bir olgun hücre tipine dönüşmesidir. Örnek: Sigara içenlerde bronş epitelinin skuamöz metaplazisi.'),
    Question(id: 'path_006', category: 'pathology', subcategory: 'general', type: 'open', difficulty: 'medium', questionText: 'Hücrenin programlanmış ölümüne ne ad verilir?', correctAnswer: 'Apoptoz', explanation: 'Apoptoz, programlanmış hücre ölümüdür. Nekrozdan farklı olarak kontrollüdür, inflamasyon yapmaz ve komşu hücrelere zarar vermez.'),
    Question(id: 'path_007', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Doku veya organın oksijensiz kalmasına ne denir?', options: ['Hipoksi', 'İskemi', 'İnfarktüs', 'Nekroz'], correctAnswer: 'İskemi', explanation: 'İskemi, doku veya organa yeterli kan gitmemesi sonucu oluşan oksijensizliktir. Uzun sürerse infarktüs gelişir.'),
    Question(id: 'path_008', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Koagülatif nekroz en sık hangi organda görülür?', options: ['Beyin', 'Kalp', 'Karaciğer', 'Akciğer'], correctAnswer: 'Kalp', explanation: 'Koagülatif nekroz, iskemik organ hasarında (özellikle kalp, böbrek) en sık görülen nekroz tipidir. Hücre sınırları bir süre korunur.'),
    Question(id: 'path_009', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Likefaktif nekroz en sık hangi organda görülür?', options: ['Kalp', 'Böbrek', 'Beyin', 'Dalak'], correctAnswer: 'Beyin', explanation: 'Likefaktif (sıvılaşma) nekrozu en sık beyinde görülür. Ayrıca bakteriyel enfeksiyonlarda apse oluşumu likefaktif nekroz örneğidir.'),
    Question(id: 'path_010', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Tromboz nedir?', options: ['Damar dışına kanama', 'Damar içinde pıhtı oluşumu', 'Damar tıkanıklığı', 'Damar genişlemesi'], correctAnswer: 'Damar içinde pıhtı oluşumu', explanation: 'Tromboz, canlı damar içinde kan pıhtısı (trombüs) oluşmasıdır. Virchow triadı (endotel hasarı, staz, hiperkoagülabilite) risk faktörlerini tanımlar.'),
    Question(id: 'path_011', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Emboli nedir?', options: ['Damar içi pıhtı', 'Kan dolaşımıyla taşınan ve damarı tıkayan parça', 'Damar duvarı kalınlaşması', 'Damar iltihabı'], correctAnswer: 'Kan dolaşımıyla taşınan ve damarı tıkayan parça', explanation: 'Emboli, kan akımıyla taşınan ve uzak bir damarı tıkayan katı, sıvı veya gaz parçacığıdır. En sık pulmoner emboli görülür.'),
    Question(id: 'path_012', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'easy', questionText: 'Benign tümör ile malign tümörün en önemli farkı nedir?', options: ['Boyut farkı', 'Metastaz yapıp yapmama', 'Ağrı yapıp yapmama', 'Renk farkı'], correctAnswer: 'Metastaz yapıp yapmama', explanation: 'Malign tümörler (kanser) metastaz yapar (uzak organlara yayılır), benign tümörler yapmaz. Bu en önemli ayırt edici özelliktir.'),
    Question(id: 'path_013', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Amiloidoz nedir?', options: ['Yağ birikimi', 'Anormal protein birikimi', 'Kalsiyum birikimi', 'Demir birikimi'], correctAnswer: 'Anormal protein birikimi', explanation: 'Amiloidoz, dokularda anormal katlanmış fibröz proteinlerin (amiloid) birikmesidir. Organ fonksiyon bozukluğuna yol açabilir.'),
    Question(id: 'path_014', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Ödem nedir?', options: ['Kan kaybı', 'Dokularda aşırı sıvı birikimi', 'Kemik erimesi', 'Kas kaybı'], correctAnswer: 'Dokularda aşırı sıvı birikimi', explanation: 'Ödem, interstisyel aralıkta veya vücut boşluklarında aşırı sıvı birikmesidir. Hidrostatik basınç artışı, onkotik basınç azalması, kapiller geçirgenlik artışı gibi nedenlerle oluşur.'),
    Question(id: 'path_015', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Granülom yapısı en çok hangi hastalıkla ilişkilidir?', options: ['Grip', 'Tüberküloz', 'Hepatit B', 'Pnömoni'], correctAnswer: 'Tüberküloz', explanation: 'Kazeöz nekrozlu granülom, tüberkülozun (TB) karakteristik histopatolojik bulgusudur. Granülomlar epiteloid histiyositler ve dev hücrelerden oluşur.'),
  ];
}
